'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const layers=['Test cases','Domain language','Protocol drivers','System under test'];
const uid=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');
const initial=()=>({version:1,project:'Court booking',tests:[
{id:'overlap',title:'Reject overlapping court bookings',path:'tests/intent/overlap.feature',kind:'Gherkin / BDD',layer:1,classification:'intent',owner:'Product & engineering',reason:'A court must never be double-booked. This is a user promise, independent of storage or transport.',revision:1,code:'@intent\nFeature: Exclusive court bookings\n\n  Scenario: Reject an overlapping booking\n    Given Court 1 is booked from 10:00 to 11:00\n    When another player books Court 1 from 10:30 to 11:30\n    Then the booking is rejected\n    And the original booking is unchanged\n'},
{id:'adjacent',title:'Adjacent bookings do not overlap',path:'tests/intent/adjacent.test.ts',kind:'Unit test',layer:1,classification:'intent',owner:'Product & engineering',reason:'One booking may start at exactly the time another ends. A domain unit test captures the same enduring promise as a scenario.',revision:1,code:'// @intent — stable domain rule\nit("allows a booking to start when another ends", () => {\n  const existing = interval("10:00", "11:00");\n  const requested = interval("11:00", "12:00");\n\n  expect(overlaps(existing, requested)).toBe(false);\n});\n'},
{id:'courts',title:'Different courts can be booked together',path:'tests/intent/separate-courts.feature',kind:'Gherkin / BDD',layer:1,classification:'intent',owner:'Product & engineering',reason:'Court availability is independent. A booking on one court must not block the other.',revision:1,code:'@intent\nFeature: Independent court availability\n\n  Scenario: Book a different court at the same time\n    Given Court 1 is booked from 10:00 to 11:00\n    When a player books Court 2 from 10:00 to 11:00\n    Then the booking is accepted\n'},
{id:'dsl',title:'Booking vocabulary',path:'tests/support/booking-dsl.ts',kind:'Supporting artifact',layer:2,classification:'implementation',owner:'Engineering',reason:'Domain vocabulary translates examples into actions. Review any change that weakens a protected assertion.',revision:1,code:'export class BookingLanguage {\n  constructor(private driver: BookingDriver) {}\n\n  async bookCourt(court: number, start: string, end: string) {\n    return this.driver.createBooking({ court, start, end });\n  }\n}\n'},
{id:'driver',title:'Booking API driver',path:'tests/drivers/booking-api.ts',kind:'Supporting artifact',layer:3,classification:'implementation',owner:'Engineering',reason:'Transport details may evolve while preserving the behaviour exercised by the contract.',revision:1,code:'export class BookingDriver {\n  constructor(private baseUrl: string) {}\n\n  async createBooking(booking: BookingRequest) {\n    return fetch(`${this.baseUrl}/bookings`, {\n      method: "POST",\n      headers: { "Content-Type": "application/json" },\n      body: JSON.stringify(booking),\n    });\n  }\n}\n'},
{id:'cache',title:'Cache keys include the court identifier',path:'tests/unit/availability-cache.test.ts',kind:'Unit test',layer:4,classification:'implementation',owner:'Engineering',reason:'This verifies a caching design choice. The implementation may be replaced while intent stays true.',revision:1,code:'it("scopes cache entries to each court", () => {\n  expect(cacheKey(1, "2026-11-01"))\n    .not.toBe(cacheKey(2, "2026-11-01"));\n});\n'}],proposals:[],history:[]});
let state=initial(), storageOk=true;
const key='intent-dd-workspace-v1';
function validPath(p){return typeof p==='string'&&p.length>0&&!/[\\\x00-\x1f:*?"<>|]/.test(p)&&!p.startsWith('/')&&p.split('/').every(x=>x&&x!=='.'&&x!=='..')&&!p.startsWith('.git/');}
function validTest(t){return t&&['id','title','path','kind','classification','owner','reason','code'].every(k=>typeof t[k]==='string')&&t.id&&t.title&&t.owner&&t.reason&&validPath(t.path)&&['Gherkin / BDD','Unit test','Supporting artifact'].includes(t.kind)&&['intent','implementation'].includes(t.classification)&&Number.isInteger(t.layer)&&t.layer>=1&&t.layer<=4&&Number.isInteger(t.revision)&&t.revision>0;}
function validate(s){if(!s||s.version!==1||typeof s.project!=='string'||!Array.isArray(s.tests)||!s.tests.every(validTest)||new Set(s.tests.map(t=>t.id)).size!==s.tests.length||new Set(s.tests.map(t=>t.path)).size!==s.tests.length||!Array.isArray(s.proposals)||!Array.isArray(s.history))throw Error('Invalid workspace format.');for(const p of s.proposals){if(!p||typeof p.id!=='string'||!['edit','delete','demote'].includes(p.action)||!validTest(p.before)||!Number.isInteger(p.baseRevision)||typeof p.reason!=='string'||typeof p.created!=='string'||(p.after!==null&&!validTest(p.after)))throw Error('Invalid review proposal.');}for(const h of s.history)if(!h||['title','action','decision','reviewer','note','date'].some(k=>typeof h[k]!=='string'))throw Error('Invalid decision history.');return s;}
try{const saved=localStorage.getItem(key);if(saved)state=validate(JSON.parse(saved));}catch(e){storageOk=false;}
let selected=state.tests[0]?.id, activeTab='library',editing=null,decision=null;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4000);}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));storageOk=true;}catch{storageOk=false;toast('Browser storage unavailable. Export a backup before leaving.');}render();}
function setTab(tab){activeTab=tab;for(const n of ['library','reviews','protocol','export'])$('#'+n).hidden=n!==tab;document.querySelectorAll('[data-tab]').forEach(n=>n.classList.toggle('active',n.dataset.tab===tab));render();}
function tags(t){return `<span class="tag ${t.classification==='intent'?'intent':''}">${t.classification==='intent'?'◆ INTENT':'IMPLEMENTATION'}</span><span class="tag">${esc(t.kind)}</span>`;}
function render(){const count=state.tests.filter(t=>t.classification==='intent').length;$('#stats').innerHTML=`<div class="stat"><b>${state.tests.length}</b><span>artifacts</span></div><div class="stat"><b>${count}</b><span>intent protected</span></div><div class="stat"><b>${state.tests.length-count}</b><span>AI editable</span></div><div class="stat"><b>${state.proposals.length}</b><span>awaiting review</span></div>`;$('#queueCount').textContent=state.proposals.length?`(${state.proposals.length})`:'';$('#fileCount').textContent=state.tests.length+' files';renderFiles();renderDetail();renderReviews();$('#layers').innerHTML=layers.map((l,i)=>`<div class="layer"><div class="layer-num">0${i+1}</div><div><h3>${l}</h3><p>${['Examples of required behaviour, expressed in domain terms. Gherkin or code can carry the contract.','A shared vocabulary for setting up and expressing business actions.','Adapters that exercise a UI, API, or other system interface.','The implementation being exercised by the test infrastructure.'][i]}</p></div><span class="tag">${state.tests.filter(t=>t.layer===i+1).length} artifacts</span></div>`).join('');}
function renderFiles(){let q=$('#search').value.toLowerCase(),f=$('#filter').value;const shown=state.tests.filter(t=>(f==='all'||t.classification===f)&&(t.title+' '+t.path).toLowerCase().includes(q));$('#files').innerHTML=shown.map(t=>`<button class="file ${selected===t.id?'selected':''}" data-file="${esc(t.id)}" aria-pressed="${selected===t.id}"><div class="tags">${tags(t)}${state.proposals.some(p=>p.before.id===t.id)?'<span class="tag pending">REVIEW</span>':''}</div><div class="file-title">${esc(t.title)}</div><div class="path">${esc(t.path)}</div></button>`).join('')||'<div class="empty">No matching artifacts.<br>Try a different filter or add a file.</div>';}
function renderDetail(){const t=state.tests.find(t=>t.id===selected);if(!t){$('#detail').innerHTML='<div class="empty">Select an artifact, or add your first test.</div>';return;}const intent=t.classification==='intent',pending=state.proposals.some(p=>p.before.id===t.id);$('#detail').innerHTML=`<div class="panel-head"><span class="eyebrow">Accepted baseline / v${t.revision}</span><span class="tag">L${t.layer} · ${layers[t.layer-1]}</span></div><div class="detail-body"><div class="detail-title"><div><h2>${esc(t.title)}</h2><div class="path">${esc(t.path)}</div></div><div class="tags" style="align-content:start">${tags(t)}</div></div><div class="notice ${intent?'':'amber'}"><b>${intent?'◆ Human review required':'AI-editable implementation'}</b><br>${intent?'Edits, deletion, renaming, and removing the intent classification are submitted as proposals. The accepted source stays unchanged until review.':'Changes can be applied directly. Promote this artifact if it defines a behaviour the system must preserve.'}</div><div class="meta"><div><small>REVIEW OWNER</small><strong>${esc(t.owner)}</strong></div><div><small>PROTECTED SCOPE</small><strong>${intent?'Entire file · source & metadata':'No protected baseline'}</strong></div></div><label>CLASSIFICATION RATIONALE</label><p style="font-size:13px">${esc(t.reason)}</p><div class="code-label"><span>ACCEPTED SOURCE</span><span>${esc(t.kind)} · not executed</span></div><pre class="code-box">${esc(t.code)}</pre>${pending?'<div class="notice amber">A change is awaiting review. Resolve it before creating another proposal.</div>':''}<div class="actions"><button class="primary" data-act="edit" ${pending?'disabled':''}>${intent?'Propose change':'Edit artifact'}</button><button data-act="classify" ${pending?'disabled':''}>${intent?'Request removal of intent':'Classify as intent'}</button><button class="quiet danger" data-act="delete" ${pending?'disabled':''}>${intent?'Propose deletion':'Delete artifact'}</button></div><p class="hint">Protection is a workflow rule in this prototype. Export a trusted repository check to detect source changes outside this browser.</p></div>`;}
function renderReviews(){$('#reviewList').innerHTML=state.proposals.map(p=>{const t=state.tests.find(t=>t.id===p.before.id),stale=!t||t.revision!==p.baseRevision;return `<article class="panel review-card"><div class="panel-head"><div><span class="tag pending">${esc(p.action.toUpperCase())} · HUMAN REVIEW</span><h3 style="margin:8px 0 0">${esc(p.before.title)}</h3></div><span class="path">v${p.baseRevision} → v${p.baseRevision+1}</span></div><div class="detail-body"><p><b>Proposed reason:</b> ${esc(p.reason)}</p><div class="diffs"><div><label>ACCEPTED · ${esc(p.before.path)} · ${esc(p.before.classification)} · L${p.before.layer}</label><p class="hint">${esc(p.before.title)} · ${esc(p.before.owner)}<br>${esc(p.before.reason)}</p><pre class="code-box">${esc(p.before.code)}</pre></div><div><label>PROPOSED · ${p.after?esc(p.after.path)+' · '+esc(p.after.classification)+' · L'+p.after.layer:'DELETE ARTIFACT'}</label><p class="hint">${p.after?esc(p.after.title)+' · '+esc(p.after.owner)+'<br>'+esc(p.after.reason):'The complete artifact will be removed.'}</p><pre class="code-box">${p.after?esc(p.after.code):'— deleted —'}</pre></div></div>${stale?'<div class="notice amber">The accepted revision has changed. This proposal is stale and cannot be approved.</div>':''}<div class="review-fields"><div><label for="reviewer-${esc(p.id)}">Reviewer name · self-declared</label><input id="reviewer-${esc(p.id)}" placeholder="Your name" maxlength="100"></div><div><label for="note-${esc(p.id)}">Decision rationale · required</label><input id="note-${esc(p.id)}" placeholder="Why should this change be accepted or rejected?" maxlength="1000"></div></div><div class="actions"><button class="primary" data-review="approve" data-id="${esc(p.id)}" ${stale?'disabled':''}>Approve exact revision</button><button data-review="reject" data-id="${esc(p.id)}">Reject proposal</button></div><p class="hint">Local workflow only. In production, reviewer identity and authorization must come from your repository provider.</p></div></article>`;}).join('')||'<div class="panel empty"><h2>No changes waiting.</h2><p>The accepted intent is stable. Propose a change from the test library to start a review.</p><button data-tab="library">Back to the library</button></div>';$('#historyCount').textContent=`(${state.history.length})`;$('#history').innerHTML=state.history.slice().reverse().map(h=>`<div style="padding:15px 0;border-bottom:1px solid var(--line)"><span class="tag ${h.decision==='approved'?'intent':''}">${esc(h.decision)}</span> <b>${esc(h.title)}</b><p class="hint">${esc(h.action)} · ${esc(h.reviewer)} · ${esc(new Date(h.date).toLocaleString())}<br>${esc(h.note)}</p></div>`).join('')||'<p class="hint">No decisions recorded yet.</p>';}
function openEditor(t){editing=t?.id||null;$('#editForm').reset();$('#editorEyebrow').textContent=t?.classification==='intent'?'Propose an intent change':'Define the contract';$('#editorTitle').textContent=t?'Revise this artifact.':'Add a test or supporting artifact.';for(const [input,prop]of Object.entries({titleInput:'title',pathInput:'path',kindInput:'kind',layerInput:'layer',classificationInput:'classification',ownerInput:'owner',reasonInput:'reason',codeInput:'code'}))if(t)$('#'+input).value=t[prop];$('#saveEdit').textContent=t?.classification==='intent'?'Submit for human review':t?'Apply change':'Add artifact';$('#editHint').textContent=t?.classification==='intent'?'All changes, including classification and path, require review. Accepted source will not change yet.':'Choose intent when this artifact captures a lasting promise. An @intent tag alone is not enforced; the policy is the source of classification.';$('#editor').showModal();}
function propose(before,after,action,reason){state.proposals.push({id:uid(),before:structuredClone(before),after:after?structuredClone(after):null,action,reason,baseRevision:before.revision,created:new Date().toISOString()});persist();toast('Proposal created. Accepted intent is unchanged.');setTab('reviews');}
function act(action){const t=state.tests.find(t=>t.id===selected);if(!t||state.proposals.some(p=>p.before.id===t.id))return;if(action==='edit'){openEditor(t);return;}if(action==='classify'&&t.classification!=='intent'){openEditor(t);$('#classificationInput').value='intent';$('#editHint').textContent='Explain why this is an enduring promise. Saving establishes the accepted protected baseline.';return;}if(t.classification==='intent'){decision={id:t.id,action:action==='delete'?'delete':'demote'};$('#decisionTitle').textContent=action==='delete'?'Request deletion of this artifact.':'Request removal of intent protection.';$('#decisionReason').value='';$('#decisionDialog').showModal();}else if(confirm('Delete this implementation artifact? Export a backup if you need to restore it.')){state.tests=state.tests.filter(x=>x.id!==t.id);selected=state.tests[0]?.id;persist();toast('Implementation artifact deleted.');}}
function applyDecision(id,approve,reviewer,note){const p=state.proposals.find(p=>p.id===id);if(!p||!reviewer.trim()||!note.trim())return false;const t=state.tests.find(t=>t.id===p.before.id);if(approve&&(!t||t.revision!==p.baseRevision||JSON.stringify(t)!==JSON.stringify(p.before))){toast('Proposal is stale. Reject it and create a new revision.');return false;}if(approve&&p.after&&state.tests.some(t=>t.id!==p.before.id&&t.path===p.after.path)){toast('That file path is already in use. Reject and revise the proposal.');return false;}if(approve){if(p.after)state.tests=state.tests.map(t=>t.id===p.before.id?{...p.after,id:p.before.id,revision:t.revision+1}:t);else state.tests=state.tests.filter(t=>t.id!==p.before.id);}state.history.push({title:p.before.title,action:p.action,decision:approve?'approved':'rejected',reviewer:reviewer.trim(),note:note.trim(),date:new Date().toISOString()});state.proposals=state.proposals.filter(x=>x.id!==id);persist();toast(approve?'Approved revision applied to the local baseline.':'Rejected. Accepted contract is unchanged.');return true;}
$('#editForm').addEventListener('submit',e=>{e.preventDefault();const old=state.tests.find(t=>t.id===editing),t={id:old?.id||uid(),title:$('#titleInput').value.trim(),path:$('#pathInput').value.trim(),kind:$('#kindInput').value,layer:Number($('#layerInput').value),classification:$('#classificationInput').value,owner:$('#ownerInput').value.trim(),reason:$('#reasonInput').value.trim(),code:$('#codeInput').value,revision:old?.revision||1};if(!validTest(t)){toast('Use a valid relative path and fill in all fields.');return;}if(state.tests.some(x=>x.id!==t.id&&x.path===t.path)){toast('This path already exists. Edit the existing artifact.');return;}if(old&&state.proposals.some(p=>p.before.id===old.id)){toast('Resolve the pending proposal first.');return;}$('#editor').close();if(old?.classification==='intent')propose(old,t,'edit',t.reason);else{if(old)state.tests=state.tests.map(x=>x.id===old.id?{...t,revision:old.revision+1}:x);else state.tests.push(t);selected=t.id;persist();toast(t.classification==='intent'?'Intent baseline accepted and protected locally.':'Artifact saved.');}});
$('#decisionForm').addEventListener('submit',e=>{e.preventDefault();const t=state.tests.find(t=>t.id===decision?.id),reason=$('#decisionReason').value.trim();if(!t||!reason)return;$('#decisionDialog').close();propose(t,decision.action==='delete'?null:{...t,classification:'implementation',reason},decision.action,reason);});
$('#cancelEdit').onclick=()=>$('#editor').close();$('#cancelDecision').onclick=()=>$('#decisionDialog').close();$('#addButton').onclick=()=>openEditor();$('#search').oninput=renderFiles;$('#filter').onchange=renderFiles;$('#projectName').value=state.project;$('#projectName').onchange=e=>{state.project=e.target.value.trim()||'Untitled project';e.target.value=state.project;persist();};
document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]'),file=e.target.closest('[data-file]'),action=e.target.closest('[data-act]'),review=e.target.closest('[data-review]');if(tab)setTab(tab.dataset.tab);if(file){selected=file.dataset.file;renderFiles();renderDetail();}if(action)act(action.dataset.act);if(review){const id=review.dataset.id;const inputs=[...$('#reviewList').querySelectorAll('input')];const who=inputs.find(n=>n.id==='reviewer-'+id),note=inputs.find(n=>n.id==='note-'+id);if(!who.value.trim()||!note.value.trim()){toast('Enter a reviewer name and decision rationale.');(!who.value.trim()?who:note).focus();return;}applyDecision(id,review.dataset.review==='approve',who.value,note.value);}});
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast(name+' exported.');}
async function policy(){const protectedFiles=await Promise.all(state.tests.filter(t=>t.classification==='intent').map(async t=>({...t,sha256:Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(t.code)))).map(x=>x.toString(16).padStart(2,'0')).join('')})));return{schemaVersion:1,project:state.project,generatedAt:new Date().toISOString(),scope:'whole-file',reviewPolicy:'Human approval required for edits, deletion, rename, reclassification, and policy changes. Enforce in trusted CI and protected repository rules.',protectedFiles};}
$('#policyExport').onclick=async()=>{try{download('intent-policy.json',JSON.stringify(await policy(),null,2),'application/json');}catch{toast('SHA-256 unavailable. Open the app over HTTPS to export policy.');}};
$('#backupExport').onclick=()=>download('intent-dd-workspace.json',JSON.stringify(state,null,2),'application/json');
$('#restoreButton').onclick=()=>$('#backupFile').click();$('#backupFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5e6)throw Error('Backup exceeds 5 MB.');const next=validate(JSON.parse(await f.text()));if(confirm('Replace this browser workspace with the backup? Existing local data will be replaced.')){state=next;selected=state.tests[0]?.id;$('#projectName').value=state.project;persist();toast('Workspace restored. Local reviews are not proof of repository approval.');}}catch(err){toast(err.message||'Invalid backup.');}e.target.value='';};
$('#importButton').onclick=()=>$('#sourceFiles').click();$('#sourceFiles').onchange=async e=>{let added=0,skipped=0;for(const f of e.target.files){if(f.size>500000){skipped++;continue;}const path=f.webkitRelativePath||f.name;if(!validPath(path)||state.tests.some(t=>t.path===path)){skipped++;continue;}const code=await f.text();if(code.includes('\0')){skipped++;continue;}state.tests.push({id:uid(),title:f.name,path,kind:f.name.endsWith('.feature')?'Gherkin / BDD':/test|spec/i.test(f.name)?'Unit test':'Supporting artifact',layer:1,classification:'implementation',owner:'Unassigned',reason:'Imported without automatic classification. Review the source and classify it explicitly.',code,revision:1});added++;}if(added)selected=state.tests[state.tests.length-added].id;persist();setTab('library');toast(`Imported ${added} files; skipped ${skipped} duplicate, binary, invalid, or oversized files. Classify intent explicitly.`);e.target.value='';};
$('#promptExport').onclick=()=>{const lines=['# AI development contract: '+state.project,'','## Non-negotiable workflow','Work one example at a time. Establish the required behaviour with a human before implementing. Observe the test fail, implement the smallest change, then run the protected contract and relevant regression tests. Never claim tests passed without execution.','','## Intent boundary','The accepted files below are human-owned. Do not edit, delete, rename, skip, weaken, or reclassify them without an explicit human-reviewed repository change. Do not alter fixtures, step definitions, assertions, drivers, or test configuration to evade them. Submit a proposed diff and rationale instead. A local browser decision is not a repository authorization.','', 'Use intent-policy.json from the trusted base branch with the trusted check_intent.py. Policy, checker, and workflow changes require protected human review. Implementation tests may evolve but must preserve the accepted behaviour.','','## Four-layer structure','Separate domain test cases, domain language, protocol drivers, and the system under test. Unit tests can also capture domain intent; syntax does not determine ownership.','','## Accepted intent'];for(const t of state.tests.filter(t=>t.classification==='intent'))lines.push('',`### ${t.title}`,`Path: ${t.path}`,`Review owner: ${t.owner}`,`Reason: ${t.reason}`,'','~~~~',t.code,'~~~~');lines.push('','## Implementation artifacts',...state.tests.filter(t=>t.classification!=='intent').map(t=>`- ${t.path}: ${t.reason}`),'','## Reporting','List changed files, test commands actually executed, results, and any proposed intent changes. Stop for human review if passing requires a contract change.');download('AI-INSTRUCTIONS.md',lines.join('\n'));};
$('#guardExport').onclick=async()=>{try{const r=await fetch('check_intent.py');if(!r.ok)throw Error();download('check_intent.py',await r.text());}catch{toast('Could not download the checker. Try again.');}};
render();if(!storageOk)toast('Saved workspace could not be loaded. Export a backup before leaving.');
